cat > /tmp/probe.py << 'PY'
import subprocess, os, json, signal, time, sys
def run(args, scenario=None, env_extra=None, inp=None, backend_args=None):
    # clean mock log
    open("/tmp/mock.log","w").close()
    if scenario is None:
        try: os.remove("/tmp/scenario.json")
        except: pass
    else:
        with open("/tmp/scenario.json","w") as f: json.dump(scenario,f)
    # start mock
    proc=subprocess.Popen(["python3","/tmp/mock2.py"], stdout=open("/tmp/mock_stdout.log","w"), stderr=subprocess.STDOUT)
    time.sleep(0.4)
    env=os.environ.copy()
    for k in list(env):
        if k.startswith("AWS") or k.startswith("CHAMBER"): del env[k]
    env.update({
        "AWS_ACCESS_KEY_ID":"test","AWS_SECRET_ACCESS_KEY":"test","AWS_REGION":"us-east-1",
        "AWS_ENDPOINT_URL_SSM":"http://127.0.0.1:18080",
        "AWS_ENDPOINT_URL_SECRETSMANAGER":"http://127.0.0.1:18080",
        "AWS_ENDPOINT_URL_S3":"http://127.0.0.1:18080",
        "AWS_ENDPOINT_URL_KMS":"http://127.0.0.1:18080",
        "AWS_ENDPOINT_URL":"http://127.0.0.1:18080",
    })
    if env_extra: env.update(env_extra)
    cmd=["./executable"]
    if backend_args: cmd+=backend_args
    cmd+=args
    try:
        p=subprocess.run(cmd, input=inp, capture_output=True, text=True, env=env, timeout=15)
        out=p.stdout; err=p.stderr; rc=p.returncode
    except subprocess.TimeoutExpired as e:
        out=(e.stdout or b'').decode() if isinstance(e.stdout,bytes) else (e.stdout or "")
        err="TIMEOUT"
        rc=-999
    finally:
        proc.terminate()
        try: proc.wait(timeout=2)
        except: proc.kill()
    try: log=open("/tmp/mock.log").read()
    except: log=""
    print(f"CMD {cmd} exit={rc}\nSTDOUT:{out!r}\nSTDERR:{err!r}\nLOG:\n{log}\n---")
    return out,err,rc,log

if __name__=="__main__":
    pass
