import subprocess, os, itertools
env=os.environ.copy()
def ok(s):
    p=subprocess.run(["./executable","--backend","null","list",s], capture_output=True, text=True, env=env)
    return p.returncode==0
candidates=["svc:","svc:a",":a","a:b:c","svc::","svc: ","svc:\t","svc:=","svc:/a","svc:a/b","svc:a:b","svc: a","svc:a ","svc::a","s:a","svc:%s"%("a"*2)]
# brute generate patterns svc:X where X in charset short
chars="abAB01-._/:@#= "
found=[]
for l in range(1,3):
    for t in itertools.product(chars, repeat=l):
        s="svc:"+''.join(t)
        if ok(s): found.append(s)
print("found",found)
for c in candidates: print(c, ok(c))
PY"}

