{"command":"cat > types.go <<'EOF'
package main

import (
	"errors"
	"fmt"
	"os"
	"regexp"
	"strconv"
	"strings"
	"time"
)

var ErrSecretNotFound = errors.New("secret not found")

// SecretID identifies a secret: Service is the namespace, Key is the key.
type SecretID struct {
	Service string
	Key     string
}

func (id SecretID) String() string {
	return "/" + id.Service + "/" + id.Key
}

type Secret struct {
	ID           SecretID
	Value        string
	Version      int
	LastModified time.Time
	User         string
}

type SecretHistory struct {
	Secret Secret
}

// parse patterns
var (
	servicePattern     = regexp.MustCompile(`^[a-zA-Z0-9_\-\./]+$`)
	keyPattern         = regexp.MustCompile(`^[a-zA-Z0-9_\-\.]+$`)
	tagKeyPattern      = regexp.MustCompile(`^[a-zA-Z0-9 \+\-=._:/@]{1,128}$`)
	tagValuePattern    = regexp.MustCompile(`^[a-zA-Z0-9 \+\-=._:/@]{1,256}$`)
)

// normalize + validate service (variant A: without colon wording)
// returns normalized (lowercased) service even on error? Callers need the normalized string
// for some error messages; parseService returns normalized string and error where the error
// text itself embeds the normalized name.
func validateServiceName(service string) error {
	if !servicePattern.MatchString(service) || strings.HasPrefix(service, "/") || strings.HasSuffix(service, "/") || strings.Contains(service, "//") {
		return fmt.Errorf("Failed to validate service name '%s'. Only alphanumeric, dashes, forward slashes, full stops and underscores are allowed for service names. Service names must not start or end with a forward slash", service)
	}
	return nil
}

func validateServiceNameColon(service string) error {
	if !servicePattern.MatchString(service) || strings.HasPrefix(service, "/") || strings.HasSuffix(service, "/") || strings.Contains(service, "//") || strings.HasPrefix(service, ":") || strings.HasSuffix(service, ":") {
		return fmt.Errorf("Failed to validate service name '%s'. Only alphanumeric, dashes, forward slashes, full stops and underscores are allowed for service names, and colon followed by a label name. Service names must not start or end with a forward slash or colon", service)
	}
	return nil
}

func validateKeyName(key string) error {
	if !keyPattern.MatchString(key) {
		return fmt.Errorf("Failed to validate key name '%s'. Only alphanumeric, dashes, full stops and underscores are allowed for key names", key)
	}
	return nil
}

// parseService normalizes (lowercases) and validates, printing reserved warning.
// variantColon selects the colon wording used by list/exec commands.
func parseService(raw string, variantColon bool) (string, error) {
	svc := strings.ToLower(raw)
	var err error
	if variantColon {
		err = validateServiceNameColon(svc)
	} else {
		err = validateServiceName(svc)
	}
	if err != nil {
		return svc, err
	}
	warnReservedService(svc)
	return svc, nil
}

func warnReservedService(svc string) {
	if svc == "_chamber" {
		fmt.Fprintln(os.Stderr, "Service name _chamber is reserved for chamber's own use and will be prohibited in a future version. Please switch to a different service name.")
	}
}

// parseSecretID parses service+key for read/write/delete/history/read etc.
func parseSecretID(serviceRaw, keyRaw string) (SecretID, error) {
	svc, err := parseService(serviceRaw, false)
	if err != nil {
		return SecretID{}, fmt.Errorf("Failed to validate service: %w", err)
	}
	key := strings.ToLower(keyRaw)
	if err := validateKeyName(key); err != nil {
		return SecretID{}, fmt.Errorf("Failed to validate key: %w", err)
	}
	return SecretID{Service: svc, Key: key}, nil
}

// parse a full SSM parameter name ("/service/.../key") into a SecretID. Used when
// listing parameters returned from SSM.
// Returns ok=false when the name cannot be parsed into a valid id.
func parseSecretIDFromFullName(name string) (SecretID, bool) {
	if !strings.HasPrefix(name, "/") {
		return SecretID{}, false
	}
	idx := strings.LastIndex(name, "/")
	if idx < 0 {
		return SecretID{}, false
	}
	service := name[1:idx]
	key := name[idx+1:]
	// validate service and key without lowercasing (preserve case)
	if err := validateServiceNameForParse(service); err != nil {
		return SecretID{}, false
	}
	if err := validateKeyName(key); err != nil {
		return SecretID{}, false
	}
	return SecretID{Service: service, Key: key}, true
}

// validation used when parsing existing parameter names: service may be empty
// (e.g. "/single")
func validateServiceNameForParse(service string) error {
	if service == "" {
		return nil
	}
	if !servicePattern.MatchString(service) || strings.HasPrefix(service, "/") || strings.HasSuffix(service, "/") || strings.Contains(service, "//") {
		return fmt.Errorf("invalid service")
	}
	return nil
}

func parseDescriptionVersion(desc string) int {
	if desc == "" {
		return 0
	}
	v, err := strconv.Atoi(desc)
	if err != nil {
		return 0
	}
	return v
}

func eventForVersion(v int) string {
	if v == 1 {
		return "Created"
	}
	return "Updated"
}

func validateTagKey(k string) error {
	if !tagKeyPattern.MatchString(k) {
		return fmt.Errorf("Failed to validate tag key '%s'. Only 128 alphanumeric, space, and characters +-=._:/@ are allowed for tag keys", k)
	}
	return nil
}

func validateTagValue(v string) error {
	if !tagValuePattern.MatchString(v) {
		return fmt.Errorf("Failed to validate tag value '%s'. Only 256 alphanumeric, space, and characters +-=._:/@ are allowed for tag values", v)
	}
	return nil
}

// env var name conversion: uppercase (unless preserve) and replace - and . with _
func envVarName(key string, preserve bool) string {
	name := key
	if !preserve {
		name = strings.ToUpper(name)
	}
	name = strings.ReplaceAll(name, "-", "_")
	name = strings.ReplaceAll(name, ".", "_")
	return name
}

func formatTime(t time.Time) string {
	return t.Format("2006-01-02 15:04:05")
}
EOF
echo ok"}

