func (c *awsCfg) fetchIMDSCredentials(ctx context.Context) (*awsCredentials, string) {
	if c.imdsDisabled {
		return nil, `access disabled to EC2 IMDS via client option, or "AWS_EC2_METADATA_DISABLED" environment variable`
	}
	base := c.imdsEndpoint
	if base == "" {
		base = "http://169.254.169.254"
	}
	base = strings.TrimSuffix(base, "/")
	// try token (ignore failure)
	client := &http.Client{}
	token := ""
	{
		req, _ := http.NewRequestWithContext(ctx, "PUT", base+"/latest/api/token", nil)
		req.Header.Set("X-aws-ec2-metadata-token-ttl-seconds", "21600")
		if resp, err := client.Do(req); err == nil {
			b, _ := io.ReadAll(resp.Body)
			resp.Body.Close()
			if resp.StatusCode == 200 {
				token = string(b)
			}
		}
	}
	roleURL := base + "/latest/meta-data/iam/security-credentials/"
	var lastErr error
	for attempt := 0; attempt < 3; attempt++ {
		if attempt > 0 {
			time.Sleep(time.Duration(attempt) * 200 * time.Millisecond)
		}
		req, _ := http.NewRequestWithContext(ctx, "GET", roleURL, nil)
		if token != "" {
			req.Header.Set("X-aws-ec2-metadata-token", token)
		}
		resp, err := client.Do(req)
		if err != nil {
			lastErr = err
			continue
		}
		b, _ := io.ReadAll(resp.Body)
		resp.Body.Close()
		if resp.StatusCode != 200 {
			return nil, fmt.Sprintf("https response error StatusCode: %d, RequestID: , api error %s: %s", resp.StatusCode, "", strings.TrimSpace(string(b)))
		}
		role := strings.TrimSpace(string(b))
		if role == "" {
			return nil, fmt.Sprintf("exceeded maximum number of attempts, 3, request send failed, Get %q: %v", roleURL, lastErr)
		}
		// get credentials for role
		req2, _ := http.NewRequestWithContext(ctx, "GET", roleURL+role, nil)
		if token != "" {
			req2.Header.Set("X-aws-ec2-metadata-token", token)
		}
		resp2, err := client.Do(req2)
		if err != nil {
			return nil, fmt.Sprintf("exceeded maximum number of attempts, 3, request send failed, Get %q: %v", roleURL, err)
		}
		b2, _ := io.ReadAll(resp2.Body)
		resp2.Body.Close()
		var doc struct {
			AccessKeyId     string `json:"AccessKeyId"`
			SecretAccessKey string `json:"SecretAccessKey"`
			Token           string `json:"Token"`
		}
		if err := json.Unmarshal(b2, &doc); err != nil || doc.AccessKeyId == "" {
			return nil, "failed to decode IMDS credentials"
		}
		return &awsCredentials{AccessKey: doc.AccessKeyId, SecretKey: doc.SecretAccessKey, SessionToken: doc.Token}, ""
	}
	return nil, fmt.Sprintf("exceeded maximum number of attempts, 3, request send failed, Get %q: %v", roleURL, lastErr)
}

// ---------- AWS operation errors ----------

type awsOpError struct {
	Service   string // SSM, Secrets Manager, S3, STS
	Operation string
	// inner kind
	missingRegion bool
	s3Region      bool
	credErrMsg    string // if not empty, credentials failure (inner IMDS message)
	status        int
	requestID     string
	hostID        string
	code          string
	message       string
	typed         bool // typed exception (no "api error" prefix)
	hasHTTP       bool // http response present
	isNetwork     bool
	networkErr    string // full `Post "url": ...`
	retryExhausted bool
	maxAttempts   int
}

func (e *awsOpError) Error() string {
	prefix := fmt.Sprintf("operation error %s: %s", e.Service, e.Operation)
	if e.missingRegion {
		if e.s3Region {
			return prefix + ", failed to resolve service endpoint, endpoint rule error, A region must be set when sending requests to S3."
		}
		return prefix + ", failed to resolve service endpoint, endpoint rule error, Invalid Configuration: Missing Region"
	}
	if e.credErrMsg != "" {
		return prefix + ", get identity: get credentials: failed to refresh cached credentials, no EC2 IMDS role found, operation error ec2imds: GetMetadata, " + e.credErrMsg
	}
	inner := ""
	if e.isNetwork {
		inner = fmt.Sprintf("https response error StatusCode: 0, RequestID: %s, request send failed, %s", e.requestID, e.networkErr)
		if e.Service == "S3" {
			// S3 network errors: does SDK include HostID? In network case no http response, format similar without host? Test showed for S3? We'll keep same without HostID for network? Actually AWS SDK for S3 includes HostID empty in http response error only when response exists.
			// keep as above
		}
	} else if e.hasHTTP {
		if e.Service == "S3" {
			if e.typed {
				inner = fmt.Sprintf("https response error StatusCode: %d, RequestID: %s, HostID: %s, %s: %s", e.status, e.requestID, e.hostID, e.code, e.message)
			} else {
				inner = fmt.Sprintf("https response error StatusCode: %d, RequestID: %s, HostID: %s, api error %s: %s", e.status, e.requestID, e.hostID, e.code, e.message)
			}
		} else {
			if e.typed {
				inner = fmt.Sprintf("https response error StatusCode: %d, RequestID: %s, %s: %s", e.status, e.requestID, e.code, e.message)
			} else if e.code != "" {
				inner = fmt.Sprintf("https response error StatusCode: %d, RequestID: %s, api error %s: %s", e.status, e.requestID, e.code, e.message)
			} else if e.message != "" {
				inner = fmt.Sprintf("https response error StatusCode: %d, RequestID: %s, %s", e.status, e.requestID, e.message)
			} else {
				inner = fmt.Sprintf("https response error StatusCode: %d, RequestID: %s, unknown error", e.status, e.requestID)
			}
		}
	}
	if e.retryExhausted {
		return fmt.Sprintf("%s, exceeded maximum number of attempts, %d, %s", prefix, e.maxAttempts, inner)
	}
	return prefix + ", " + inner
}

func (e *awsOpError) Code() string { return e.code }

func isRetryableErr(e *awsOpError) bool {
	if e.missingRegion || e.credErrMsg != "" {
		return false
	}
	if e.isNetwork {
		return true
	}
	if e.status >= 500 || e.status == 429 || e.status == 408 {
		return true
	}
	switch e.code {
	case "Throttling", "ThrottlingException", "ThrottledException", "RequestThrottledException", "TooManyRequestsException", "ProvisionedThroughputExceededException", "TransactionInProgressException", "RequestLimitExceeded", "BandwidthLimitExceeded", "LimitExceededException", "RequestThrottled", "SlowDown", "EC2ThrottledException":
		return true
	}
	return false
}

