cat > aws.go <<'EOF'
package main

import (
	"bytes"
	"context"
	"crypto/hmac"
	"crypto/rand"
	"crypto/sha256"
	"encoding/hex"
	"encoding/json"
	"encoding/xml"
	"fmt"
	"io"
	"net/http"
	"net/url"
	"os"
	"path/filepath"
	"sort"
	"strconv"
	"strings"
	"time"
)

// ---------- credentials & config ----------

type awsCredentials struct {
	AccessKey    string
	SecretKey    string
	SessionToken string
}

type awsCfg struct {
	Region     string
	staticCred *awsCredentials // nil if none found statically
	profile    string
	maxAttempts int
	endpoints  map[string]string // service key -> endpoint url (custom, may be "")
	// imds endpoint override
	imdsEndpoint string
	imdsDisabled bool
}

func homeDir() string {
	if h, err := os.UserHomeDir(); err == nil {
		return h
	}
	return os.Getenv("HOME")
}

// minimal INI parser for AWS shared config/credentials files
type iniSection map[string]string
type iniFile map[string]iniSection

func parseINIFile(path string) iniFile {
	result := iniFile{}
	data, err := os.ReadFile(path)
	if err != nil {
		return result
	}
	current := ""
	result[current] = iniSection{}
	for _, line := range strings.Split(string(data), "\n") {
		line = strings.TrimSpace(line)
		if line == "" || strings.HasPrefix(line, "#") || strings.HasPrefix(line, ";") {
			continue
		}
		if strings.HasPrefix(line, "[") && strings.HasSuffix(line, "]") {
			current = strings.TrimSpace(line[1 : len(line)-1])
			if _, ok := result[current]; !ok {
				result[current] = iniSection{}
			}
			continue
		}
		var k, v string
		if idx := strings.Index(line, "="); idx >= 0 {
			k = strings.TrimSpace(line[:idx])
			v = strings.TrimSpace(line[idx+1:])
		} else if idx := strings.Index(line, ":"); idx >= 0 {
			k = strings.TrimSpace(line[:idx])
			v = strings.TrimSpace(line[idx+1:])
		} else {
			continue
		}
		result[current][strings.ToLower(k)] = v
	}
	return result
}

func configProfileName() (name string, explicit bool) {
	if v := os.Getenv("AWS_PROFILE"); v != "" {
		return v, true
	}
	if v := os.Getenv("AWS_DEFAULT_PROFILE"); v != "" {
		return v, true
	}
	return "default", false
}

func loadAWSConfig(maxAttempts int) (*awsCfg, error) {
	profile, explicit := configProfileName()
	credPath := os.Getenv("AWS_SHARED_CREDENTIALS_FILE")
	if credPath == "" {
		credPath = filepath.Join(homeDir(), ".aws", "credentials")
	}
	cfgPath := os.Getenv("AWS_CONFIG_FILE")
	if cfgPath == "" {
		cfgPath = filepath.Join(homeDir(), ".aws", "config")
	}
	credFile := parseINIFile(credPath)
	cfgFile := parseINIFile(cfgPath)
	// helper to get profile section
	credSection := func() iniSection {
		if s, ok := credFile[profile]; ok {
			return s
		}
		return nil
	}
	cfgSection := func() iniSection {
		// config file sections are "profile <name>" except default
		if profile == "default" {
			if s, ok := cfgFile["default"]; ok {
				return s
			}
		}
		if s, ok := cfgFile["profile "+profile]; ok {
			return s
		}
		if s, ok := cfgFile[profile]; ok {
			return s
		}
		return nil
	}
	if explicit {
		_, inCred := credFile[profile]
		cs := cfgSection()
		if !inCred && cs == nil {
			return nil, fmt.Errorf("failed to get shared config profile, %s", profile)
		}
	}
	cfg := &awsCfg{profile: profile, maxAttempts: maxAttempts, endpoints: map[string]string{}}
	// region
	if v := os.Getenv("AWS_REGION"); v != "" {
		cfg.Region = v
	} else if v := os.Getenv("AWS_DEFAULT_REGION"); v != "" {
		cfg.Region = v
	} else if cs := cfgSection(); cs != nil && cs["region"] != "" {
		cfg.Region = cs["region"]
	} else if cs := credSection(); cs != nil && cs["region"] != "" {
		cfg.Region = cs["region"]
	}
	// static credentials: env first
	if ak := os.Getenv("AWS_ACCESS_KEY_ID"); ak != "" {
		if sk := os.Getenv("AWS_SECRET_ACCESS_KEY"); sk != "" {
			cfg.staticCred = &awsCredentials{AccessKey: ak, SecretKey: sk, SessionToken: os.Getenv("AWS_SESSION_TOKEN")}
		}
	}
	if cfg.staticCred == nil {
		// try profile sections (credentials file preferred, then config)
		for _, sec := range []iniSection{credSection(), cfgSection()} {
			if sec == nil {
				continue
			}
			if ak := sec["aws_access_key_id"]; ak != "" && sec["aws_secret_access_key"] != "" {
				cfg.staticCred = &awsCredentials{AccessKey: ak, SecretKey: sec["aws_secret_access_key"], SessionToken: sec["aws_session_token"]}
				break
			}
		}
	}
	// endpoint from profile config
	if cs := cfgSection(); cs != nil {
		if ep := cs["endpoint_url"]; ep != "" {
			cfg.endpoints[""] = ep
		}
	}
	if v := os.Getenv("AWS_EC2_METADATA_DISABLED"); strings.EqualFold(v, "true") {
		cfg.imdsDisabled = true
	}
	if v := os.Getenv("AWS_EC2_METADATA_SERVICE_ENDPOINT"); v != "" {
		cfg.imdsEndpoint = v
	}
	return cfg, nil
}

func (c *awsCfg) endpointFor(serviceKey string) string {
	// serviceKey: "ssm", "secretsmanager", "s3", "sts"
	envName := ""
	switch serviceKey {
	case "ssm":
		envName = "AWS_ENDPOINT_URL_SSM"
	case "secretsmanager":
		envName = "AWS_ENDPOINT_URL_SECRETSMANAGER"
	case "s3":
		envName = "AWS_ENDPOINT_URL_S3"
	case "sts":
		envName = "AWS_ENDPOINT_URL_STS"
	case "kms":
		envName = "AWS_ENDPOINT_URL_KMS"
	}
	if envName != "" {
		if v := os.Getenv(envName); v != "" {
			return v
		}
	}
	if v := os.Getenv("AWS_ENDPOINT_URL"); v != "" {
		return v
	}
	if v, ok := c.endpoints[serviceKey]; ok {
		return v
	}
	if v, ok := c.endpoints[""]; ok {
		return v
	}
	return ""
}

func (c *awsCfg) resolveCredentials(ctx context.Context, serviceDisplay, operation string) (*awsCredentials, *awsOpError) {
	if c.staticCred != nil {
		return c.staticCred, nil
	}
	// IMDS
	creds, imdsErrStr := c.fetchIMDSCredentials(ctx)
	if creds != nil {
		// cache
		c.staticCred = creds
		return creds, nil
	}
	return nil, &awsOpError{
		Service: serviceDisplay, Operation: operation,
		credErrMsg: imdsErrStr,
	}
}

func (c *awsCfg) fetchIMDSCredentials(ctx context.Context) (*awsCredentials, string) {
	if c.imdsDisabled {
		return nil, `access disabled to EC2 IMDS via client option, or "AWS_EC2_METADATA_DISABLED" environment variable`
	}
	base := c.imdsEndpoint
	if base == "" {
		base = "http://169.254.169.254"
	}
	base = strings.TrimSuffix(base, "/")
	// try token (ignore failure)
	client := &http.Client{}
	token := ""
	{
		req, _ := http.NewRequestWithContext(ctx, "PUT", base+"/latest/api/token", nil)
		req.Header.Set("X-aws-ec2-metadata-token-ttl-seconds", "21600")
		if resp, err := client.Do(req); err == nil {
			b, _ := io.ReadAll(resp.Body)
			resp.Body.Close()
			if resp.StatusCode == 200 {
				token = string(b)
			}
		}
	}
	roleURL := base + "/latest/meta-data/iam/security-credentials/"
	var lastErr error
	for attempt := 0; attempt < 3; attempt++ {
		if attempt > 0 {
			time.Sleep(time.Duration(attempt) * 200 * time.Millisecond)
		}
		req, _ := http.NewRequestWithContext(ctx, "GET", roleURL, nil)
		if token != "" {
			req.Header.Set("X-aws-ec2-metadata-token", token)
		}
		resp, err := client.Do(req)
		if err != nil {
			lastErr = err
			continue
		}
		b, _ := io.ReadAll(resp.Body)
		resp.Body.Close()
		if resp.StatusCode != 200 {
			return nil, fmt.Sprintf("https response error StatusCode: %d, RequestID: , api error %s: %s", resp.StatusCode, "", strings.TrimSpace(string(b)))
		}
		role := strings.TrimSpace(string(b))
		if role == "" {
			return nil, fmt.Sprintf("exceeded maximum number of attempts, 3, request send failed, Get %q: %v", roleURL, lastErr)
		}
		// get credentials for role
		req2, _ := http.NewRequestWithContext(ctx, "GET", roleURL+role, nil)
		if token != "" {
			req2.Header.Set("X-aws-ec2-metadata-token", token)
		}
		resp2, err := client.Do(req2)
		if err != nil {
			return nil, fmt.Sprintf("exceeded maximum number of attempts, 3, request send failed, Get %q: %v", roleURL, err)
		}
		b2, _ := io.ReadAll(resp2.Body)
		resp2.Body.Close()
		var doc struct {
			AccessKeyId     string `json:"AccessKeyId"`
			SecretAccessKey string `json:"SecretAccessKey"`
			Token           string `json:"Token"`
		}
		if err := json.Unmarshal(b2, &doc); err != nil || doc.AccessKeyId == "" {
			return nil, "failed to decode IMDS credentials"
		}
		return &awsCredentials{AccessKey: doc.AccessKeyId, SecretKey: doc.SecretAccessKey, SessionToken: doc.Token}, ""
	}
	return nil, fmt.Sprintf("exceeded maximum number of attempts, 3, request send failed, Get %q: %v", roleURL, lastErr)
}

// ---------- AWS operation errors ----------

type awsOpError struct {
	Service   string // SSM, Secrets Manager, S3, STS
	Operation string
	// inner kind
	missingRegion bool
	s3Region      bool
	credErrMsg    string // if not empty, credentials failure (inner IMDS message)
	status        int
	requestID     string
	hostID        string
	code          string
	message       string
	typed         bool // typed exception (no "api error" prefix)
	hasHTTP       bool // http response present
	isNetwork     bool
	networkErr    string // full `Post "url": ...`
	retryExhausted bool
	maxAttempts   int
}

func (e *awsOpError) Error() string {
	prefix := fmt.Sprintf("operation error %s: %s", e.Service, e.Operation)
	if e.missingRegion {
		if e.s3Region {
			return prefix + ", failed to resolve service endpoint, endpoint rule error, A region must be set when sending requests to S3."
		}
		return prefix + ", failed to resolve service endpoint, endpoint rule error, Invalid Configuration: Missing Region"
	}
	if e.credErrMsg != "" {
		return prefix + ", get identity: get credentials: failed to refresh cached credentials, no EC2 IMDS role found, operation error ec2imds: GetMetadata, " + e.credErrMsg
	}
	inner := ""
	if e.isNetwork {
		inner = fmt.Sprintf("https response error StatusCode: 0, RequestID: %s, request send failed, %s", e.requestID, e.networkErr)
		if e.Service == "S3" {
			// S3 network errors: does SDK include HostID? In network case no http response, format similar without host? Test showed for S3? We'll keep same without HostID for network? Actually AWS SDK for S3 includes HostID empty in http response error only when response exists.
			// keep as above
		}
	} else if e.hasHTTP {
		if e.Service == "S3" {
			if e.typed {
				inner = fmt.Sprintf("https response error StatusCode: %d, RequestID: %s, HostID: %s, %s: %s", e.status, e.requestID, e.hostID, e.code, e.message)
			} else {
				inner = fmt.Sprintf("https response error StatusCode: %d, RequestID: %s, HostID: %s, api error %s: %s", e.status, e.requestID, e.hostID, e.code, e.message)
			}
		} else {
			if e.typed {
				inner = fmt.Sprintf("https response error StatusCode: %d, RequestID: %s, %s: %s", e.status, e.requestID, e.code, e.message)
			} else if e.code != "" {
				inner = fmt.Sprintf("https response error StatusCode: %d, RequestID: %s, api error %s: %s", e.status, e.requestID, e.code, e.message)
			} else if e.message != "" {
				inner = fmt.Sprintf("https response error StatusCode: %d, RequestID: %s, %s", e.status, e.requestID, e.message)
			} else {
				inner = fmt.Sprintf("https response error StatusCode: %d, RequestID: %s, unknown error", e.status, e.requestID)
			}
		}
	}
	if e.retryExhausted {
		return fmt.Sprintf("%s, exceeded maximum number of attempts, %d, %s", prefix, e.maxAttempts, inner)
	}
	return prefix + ", " + inner
}

func (e *awsOpError) Code() string { return e.code }

func isRetryableErr(e *awsOpError) bool {
	if e.missingRegion || e.credErrMsg != "" {
		return false
	}
	if e.isNetwork {
		return true
	}
	if e.status >= 500 || e.status == 429 || e.status == 408 {
		return true
	}
	switch e.code {
	case "Throttling", "ThrottlingException", "ThrottledException", "RequestThrottledException", "TooManyRequestsException", "ProvisionedThroughputExceededException", "TransactionInProgressException", "RequestLimitExceeded", "BandwidthLimitExceeded", "LimitExceededException", "RequestThrottled", "SlowDown", "EC2ThrottledException":
