func (c *awsCfg) endpointFor(serviceKey string) string {
	// serviceKey: "ssm", "secretsmanager", "s3", "sts"
	envName := ""
	switch serviceKey {
	case "ssm":
		envName = "AWS_ENDPOINT_URL_SSM"
	case "secretsmanager":
		envName = "AWS_ENDPOINT_URL_SECRETSMANAGER"
	case "s3":
		envName = "AWS_ENDPOINT_URL_S3"
	case "sts":
		envName = "AWS_ENDPOINT_URL_STS"
	case "kms":
		envName = "AWS_ENDPOINT_URL_KMS"
	}
	if envName != "" {
