		opErr := &awsOpError{Service: serviceDisplay, Operation: operation, status: resp.StatusCode, requestID: reqID, hostID: hostID, code: code, message: msg, typed: typed, hasHTTP: true}
		if attempt < maxAtt && isRetryableErr(opErr) {
			retryDelay(attempt); continue
		}
		if isRetryableErr(opErr) { opErr.retryExhausted = true; opErr.maxAttempts = maxAtt }
		return nil, opErr
	}
	return nil, &awsOpError{Service: serviceDisplay, Operation: operation, isNetwork: true, networkErr: "unknown"}
}

func hasSupportedChecksum(h http.Header) bool {
	for k := range h {
		lk := strings.ToLower(k)
		if lk == "x-amz-checksum-crc32" || lk == "x-amz-checksum-crc32c" || lk == "x-amz-checksum-sha1" || lk == "x-amz-checksum-sha256" || lk == "x-amz-checksum-md5" || lk == "x-amz-checksum-crc64nvme" {
			// crc64nvme is considered unsupported by older SDK? It says no supported checksum if only that? ignore.
			if lk == "x-amz-checksum-crc64nvme" {
				continue
			}
			return true
		}
	}
	return false
}

func crc32Base64(b []byte) string {
	c := crc32.ChecksumIEEE(b)
	var buf [4]byte
	buf[0] = byte(c >> 24); buf[1] = byte(c >> 16); buf[2] = byte(c >> 8); buf[3] = byte(c)
	return base64.StdEncoding.EncodeToString(buf[:])
}

