{"command":"cat > ssm.go <<'EOF'
package main

import (
	"context"
	"encoding/json"
	"errors"
	"fmt"
	"sort"
	"strconv"
	"strings"
)

// SSM parameter representations
type ssmParameter struct {
	Name    string  `json:"Name"`
	Value   *string `json:"Value"`
	Version int64   `json:"Version"`
}
type ssmParameterMeta struct {
	Name             string  `json:"Name"`
	Version          int64   `json:"Version"`
	LastModifiedDate float64 `json:"LastModifiedDate"`
	LastModifiedUser string  `json:"LastModifiedUser"`
	Description      string  `json:"Description"`
}
type ssmHistoryParam struct {
	Name             string  `json:"Name"`
	Value            *string `json:"Value"`
	Version          int64   `json:"Version"`
	LastModifiedDate float64 `json:"LastModifiedDate"`
	LastModifiedUser string  `json:"LastModifiedUser"`
	Description      string  `json:"Description"`
}

type SSMStore struct {
	cfg      *awsCfg
	kmsKeyId string // full "alias/..."
}

func (s *SSMStore) clientOp(ctx context.Context, operation string, payload interface{}) ([]byte, *awsOpError) {
	uaFeature := "g"
	switch operation {
	case "DescribeParameters", "GetParametersByPath", "GetParameterHistory":
		uaFeature = "C,g"
	}
	return s.cfg.doJSONRPC(ctx, "ssm", "SSM", operation, "AmazonSSM", "1.67.3", uaFeature, payload)
}

func timeFromEpoch(f float64) (t struct{Unix int64}) { return }

// helpers to convert epoch float seconds to time
// (defined in util file)

// listWithDescribe returns metadata secrets via DescribeParameters paginated
func (s *SSMStore) describeParameters(ctx context.Context, filters []map[string]interface{}, maxResults *int) ([]ssmParameterMeta, error) {
	var all []ssmParameterMeta
	var next *string
	for {
		payload := map[string]interface{}{}
		if maxResults != nil {
			payload["MaxResults"] = *maxResults
		}
		if filters != nil {
			payload["ParameterFilters"] = filters
		}
		if next != nil {
			payload["NextToken"] = *next
		}
		body, opErr := s.clientOp(ctx, "DescribeParameters", payload)
		if opErr != nil {
			return nil, opErr
		}
		var out struct {
			Parameters []ssmParameterMeta `json:"Parameters"`
			NextToken  *string            `json:"NextToken"`
		}
		if err := json.Unmarshal(body, &out); err != nil {
			return nil, err
		}
		all = append(all, out.Parameters...)
		if out.NextToken == nil || *out.NextToken == "" {
			break
		}
		next = out.NextToken
	}
	return all, nil
}

func (s *SSMStore) List(ctx context.Context, service string, expand bool) ([]*Secret, error) {
	filters := []map[string]interface{}{
		{"Key": "Path", "Option": "OneLevel", "Values": []string{"/" + service}},
	}
	metas, err := s.describeParameters(ctx, filters, nil)
	if err != nil {
		return nil, err
	}
	var secrets []*Secret
	// build in order returned, then sort by full id string
	for _, m := range metas {
		id, ok := parseSecretIDFromFullName(m.Name)
		if !ok {
			continue
		}
		sec := &Secret{
			ID:           id,
			Version:      parseDescriptionVersion(m.Description),
			LastModified: epochToTime(m.LastModifiedDate),
			User:         m.LastModifiedUser,
		}
		// keep full name for sorting / value lookup; store in a map keyed by name via ID string
		secrets = append(secrets, sec)
	}
	sort.SliceStable(secrets, func(i, j int) bool {
		return secrets[i].ID.String() < secrets[j].ID.String()
	})
	if expand {
		if len(secrets) == 0 {
			// still? original: if no secrets, GetParameters not called? Earlier list -e empty: no Get call? Check null etc.
			// For SSM empty list, we should not call GetParameters (makes sense)
			return secrets, nil
		}
		// build list of full names from metadata (original order from describe response, not sorted)
		// Reconstruct names list in metas order (parsed ok)
		var names []string
		nameToValue := map[string]*string{}
		// First, collect names in metas order
		for _, m := range metas {
			if _, ok := parseSecretIDFromFullName(m.Name); !ok {
				continue
			}
			names = append(names, m.Name)
		}
		// Original appears to build names from a map (random order). We will use names order as above;
		// request body order is not typically asserted.
		// GetParameters in chunks? Original sent all names in one request (observed). Keep one request.
		payload := map[string]interface{}{"Names": names, "WithDecryption": true}
		body, opErr := s.clientOp(ctx, "GetParameters", payload)
		if opErr != nil {
			return nil, opErr
		}
		var out struct {
			Parameters        []ssmParameter `json:"Parameters"`
			InvalidParameters []string       `json:"InvalidParameters"`
		}
		if err := json.Unmarshal(body, &out); err != nil {
			return nil, err
		}
		for _, p := range out.Parameters {
			nameToValue[p.Name] = p.Value
		}
		for _, sec := range secrets {
			full := sec.ID.String()
			valPtr := nameToValue[full]
			// Original panics if missing (nil deref). Mimic: dereference nil pointer.
			sec.Value = *valPtr
		}
	}
	return secrets, nil
}

func (s *SSMStore) getParameters(ctx context.Context, names []string) ([]ssmParameter, error) {
	payload := map[string]interface{}{"Names": names, "WithDecryption": true}
	body, opErr := s.clientOp(ctx, "GetParameters", payload)
	if opErr != nil {
		return nil, opErr
	}
	var out struct {
		Parameters        []ssmParameter `json:"Parameters"`
		InvalidParameters []string       `json:"InvalidParameters"`
	}
	if err := json.Unmarshal(body, &out); err != nil {
		return nil, err
	}
	return out.Parameters, nil
}

func (s *SSMStore) Read(ctx context.Context, id SecretID) (*Secret, error) {
	params, err := s.getParameters(ctx, []string{id.String()})
	if err != nil {
		return nil, err
	}
	if len(params) == 0 {
		return nil, ErrSecretNotFound
	}
	value := ""
	if params[0].Value != nil {
		value = *params[0].Value
	}
	// get metadata via List
	list, err := s.List(ctx, id.Service, false)
	if err != nil {
		return nil, err
	}
	for _, sec := range list {
		if sec.ID.Service == id.Service && sec.ID.Key == id.Key {
			sec.Value = value
			return sec, nil
		}
	}
	return nil, ErrSecretNotFound
}

func (s *SSMStore) ReadVersion(ctx context.Context, id SecretID, version int) (*Secret, error) {
	hist, err := s.getHistoryParams(ctx, id, true)
	if err != nil {
		return nil, err
	}
	for _, h := range hist {
		v := parseDescriptionVersion(h.Description)
		if v == version {
			val := ""
			if h.Value != nil {
				val = *h.Value
			}
			return &Secret{ID: id, Value: val, Version: v, LastModified: epochToTime(h.LastModifiedDate), User: h.LastModifiedUser}, nil
		}
	}
	return nil, ErrSecretNotFound
}

func (s *SSMStore) getHistoryParams(ctx context.Context, id SecretID, withDecryption bool) ([]ssmHistoryParam, error) {
	var all []ssmHistoryParam
	var next *string
	for {
		payload := map[string]interface{}{"Name": id.String(), "WithDecryption": withDecryption}
		if next != nil {
			payload["NextToken"] = *next
		}
		body, opErr := s.clientOp(ctx, "GetParameterHistory", payload)
		if opErr != nil {
			return nil, opErr
		}
		var out struct {
			Parameters []ssmHistoryParam `json:"Parameters"`
			NextToken  *string           `json:"NextToken"`
		}
		if err := json.Unmarshal(body, &out); err != nil {
			return nil, err
		}
		all = append(all, out.Parameters...)
		if out.NextToken == nil || *out.NextToken == "" {
			break
		}
		next = out.NextToken
	}
	return all, nil
}

func (s *SSMStore) History(ctx context.Context, id SecretID) ([]*Secret, error) {
	hist, err := s.getHistoryParams(ctx, id, false)
	if err != nil {
		return nil, err
	}
	var out []*Secret
	for _, h := range hist {
		v := parseDescriptionVersion(h.Description)
		val := ""
		if h.Value != nil {
			val = *h.Value
		}
		out = append(out, &Secret{ID: id, Value: val, Version: v, LastModified: epochToTime(h.LastModifiedDate), User: h.LastModifiedUser})
	}
	return out, nil
}

// store config
type ssmStoreConfig struct {
	Version string `json:"version"`
}

func (s *SSMStore) getStoreConfig(ctx context.Context) (*ssmStoreConfig, error) {
	cfgID := SecretID{Service: "_chamber", Key: "store-config"}
	sec, err := s.Read(ctx, cfgID)
	if err != nil {
		if errors.Is(err, ErrSecretNotFound) {
			return &ssmStoreConfig{}, nil
		}
		return nil, err
	}
	var cfg ssmStoreConfig
	if err := json.Unmarshal([]byte(sec.Value), &cfg); err != nil {
		return nil, fmt.Errorf("failed to unmarshal store config: %w", err)
	}
	return &cfg, nil
}

func (s *SSMStore) Write(ctx context.Context, id SecretID, value string) error {
	return s.write(ctx, id, value, nil, false)
}
func (s *SSMStore) WriteWithTags(ctx context.Context, id SecretID, value string, tags map[string]string) error {
	return s.write(ctx, id, value, tags, true)
}

func (s *SSMStore) write(ctx context.Context, id SecretID, value string, tags map[string]string, withTags bool) error {
	// read existing
	existing, err := s.Read(ctx, id)
	isNew := false
	newVersion := 1
	if err != nil {
		if errors.Is(err, ErrSecretNotFound) {
			isNew = true
			// read store config (only for new)
			if _, err := s.getStoreConfig(ctx); err != nil {
				return err
			}
		} else {
			return err
		}
	} else {
		if withTags {
			return errors.New("tags on write only supported for new secrets")
		}
		newVersion = existing.Version + 1
		_ = isNew
	}
	payload := map[string]interface{}{
		"Description": strconv.Itoa(newVersion),
		"KeyId":       s.kmsKeyId,
		"Name":        id.String(),
		"Overwrite":   true,
		"Type":        "SecureString",
		"Value":       value,
	}
	_, opErr := s.clientOp(ctx, "PutParameter", payload)
	if opErr != nil {
		return opErr
	}
	if withTags && len(tags) > 0 {
		// AddTags
		var tagList []map[string]string
		for k, v := range tags {
			tagList = append(tagList, map[string]string{"Key": k, "Value": v})
		}
		payloadTags := map[string]interface{}{
			"ResourceId":   id.String(),
			"ResourceType": "Parameter",
			"Tags":         tagList,
		}
		_, opErr := s.clientOp(ctx, "AddTagsToResource", payloadTags)
		if opErr != nil {
			return opErr
		}
	}
	return nil
}

func (s *SSMStore) Delete(ctx context.Context, id SecretID) error {
	// check existence via Read
	_, err := s.Read(ctx, id)
