func (s *SSMStore) Read(ctx context.Context, id SecretID) (*Secret, error) {
	params, err := s.getParameters(ctx, []string{id.String()})
	if err != nil {
		return nil, err
	}
	if len(params) == 0 {
		return nil, ErrSecretNotFound
	}
	value := ""
	if params[0].Value != nil {
		value = *params[0].Value
	}
	// get metadata via List
	list, err := s.List(ctx, id.Service, false)
	if err != nil {
		return nil, err
	}
	for _, sec := range list {
		if sec.ID.Service == id.Service && sec.ID.Key == id.Key {
