func (s *SSMStore) WriteTags(ctx context.Context, id SecretID, tags map[string]string, deleteOther bool, tagsSlice []Tag) error {
	if deleteOther {
		// read existing tags
		existing, err := s.ReadTags(ctx, id)
		if err != nil {
			return err
		}
		// first store-config read (matching observed behaviour in WriteTags path)
		if _, err := s.getStoreConfig(ctx); err != nil {
			return err
		}
		// determine tags to delete
		var toDelete []string
		for _, t := range existing {
			if _, ok := tags[t.Key]; !ok {
				toDelete = append(toDelete, t.Key)
			}
		}
		if len(toDelete) > 0 {
			// DeleteTags internally reads store-config again then removes
			if err := s.deleteTagsInternal(ctx, id, toDelete); err != nil {
				return err
			}
		} else {
			// If nothing to delete, original still did two config reads before Add? In earlier tests with existing tags present and needing deletion, there were 2 reads.
			// It read config in WriteTags and again presumably ??? But if no deletion, would second read happen? Unknown.
			// Observe: our earlier successful delete-other had deletions. We'll keep second read only when deleting to match that case.
			_ = existing
		}
	}
	// AddTags
	var tagList []map[string]string
	for k, v := range tags {
		tagList = append(tagList, map[string]string{"Key": k, "Value": v})
	}
	// To match Go map iteration randomness in SDK request, tagList built from map is fine.
	payload := map[string]interface{}{"ResourceId": id.String(), "ResourceType": "Parameter", "Tags": tagList}
	_, opErr := s.clientOp(ctx, "AddTagsToResource", payload)
	if opErr != nil {
		return opErr
	}
	return nil
}

func (s *SSMStore) deleteTagsInternal(ctx context.Context, id SecretID, tagKeys []string) error {
	if _, err := s.getStoreConfig(ctx); err != nil {
		return err
	}
	payload := map[string]interface{}{"ResourceId": id.String(), "ResourceType": "Parameter", "TagKeys": tagKeys}
	_, opErr := s.clientOp(ctx, "RemoveTagsFromResource", payload)
	if opErr != nil {
