		var ks []string
		for key := range data.Latest { ks = append(ks, key) }
		sort.Strings(ks)
		if len(ks) > 0 { alias = data.Latest[ks[0]].KMSAlias }
		files = append(files, kmsLatestFile{Filename: k, Alias: alias, Data: data})
