	}
	return errors.New("Not implemented for S3 Store")
}

func (s *S3Store) write(ctx context.Context, id SecretID, value string) error {
	// step1: read latest(s)
	var plainLatest s3LatestPlain
	var kmsFiles []kmsLatestFile
	var kmsCurrent *kmsLatestFile
	var kmsCurrentFilename string
	if s.isKMS {
		files, err := s.listKMSLatestFilesFull(ctx, id.Service)
		if err != nil { return err }
		kmsFiles = files
		kmsCurrentFilename = kmsLatestFilename(id.Service, s.kmsAlias)
		// find current file
		for i, f := range kmsFiles {
			if f.Filename == kmsCurrentFilename {
				kmsCurrent = &kmsFiles[i]
				break
			}
		}
		if kmsCurrent == nil {
			// create empty placeholder
			kmsCurrent = &kmsLatestFile{Filename: kmsCurrentFilename, Alias: s.kmsAlias, Data: s3LatestKMS{Latest: map[string]s3LatestKMSEntry{}}}
		}
	} else {
		lp, err := s.readPlainLatest(ctx, id.Service)
		if err != nil { return err }
		plainLatest = lp
	}
	// step2: read key file
	kf, err := s.readKeyFile(ctx, id)
	if err != nil {
		if errors.Is(err, ErrSecretNotFound) {
			kf = &s3KeyFile{Service: id.Service, Key: id.String(), Values: map[string]s3ValueEntry{}}
		} else {
			return err
		}
	}
	// user
	userArn, opErr := s.cfg.getCallerIdentity(ctx)
	if opErr != nil { return opErr }
	nowStr := time.Now().UTC().Format(time.RFC3339Nano)
	newVersion := 1
	if e, ok := latestEntry(kf); ok {
		newVersion = e.Version + 1
	}
	if kf.Values == nil { kf.Values = map[string]s3ValueEntry{} }
	kf.Service = id.Service
	kf.Key = id.String()
	kf.Values[strconv.Itoa(newVersion)] = s3ValueEntry{Created: nowStr, CreatedBy: userArn, Version: newVersion, Value: value}
	blob, _ := json.Marshal(kf)
	if opErr := s.putObject(ctx, fmt.Sprintf("%s/%s.json", id.Service, id.Key), blob); opErr != nil { return opErr }
	// update latest
	if s.isKMS {
		if kmsCurrent.Data.Latest == nil { kmsCurrent.Data.Latest = map[string]s3LatestKMSEntry{} }
		kmsCurrent.Data.Latest[id.Key] = s3LatestKMSEntry{Version: newVersion, Value: value, KMSAlias: s.kmsAlias}
		lblob, _ := json.Marshal(kmsCurrent.Data)
		if opErr := s.putObjectWithAlias(ctx, kmsCurrentFilename, lblob, s.kmsAlias); opErr != nil { return opErr }
	} else {
		if plainLatest.Latest == nil { plainLatest.Latest = map[string]string{} }
		plainLatest.Latest[id.Key] = value
		lblob, _ := json.Marshal(plainLatest)
		if opErr := s.putObject(ctx, fmt.Sprintf("%s/__latest.json", id.Service), lblob); opErr != nil { return opErr }
	}
	return nil
}

func (s *S3Store) Delete(ctx context.Context, id SecretID) error {
	if s.isKMS {
		files, err := s.listKMSLatestFilesFull(ctx, id.Service)
		if err != nil { return err }
		// delete object
		if opErr := s.deleteObject(ctx, fmt.Sprintf("%s/%s.json", id.Service, id.Key)); opErr != nil { return opErr }
		// find file(s) containing key, update each? Original updated only the file that contained key (one). If multiple, maybe ... We'll update all containing to be safe? But original test with single file updated that one.
		// Determine first containing file
		updated := false
		for _, f := range files {
			if _, ok := f.Data.Latest[id.Key]; ok {
				delete(f.Data.Latest, id.Key)
				lblob, _ := json.Marshal(f.Data)
				alias := f.Alias
				if alias == "" { alias = s.kmsAlias }
				if opErr := s.putObjectWithAlias(ctx, f.Filename, lblob, alias); opErr != nil { return opErr }
				updated = true
				break
			}
		}
		if !updated {
			// No file contains key: original behaviour? For plain it created an empty latest. For KMS unknown. It may not put any.
			// But early delete missing test for plain created latest. For KMS, we leave as is.
		}
		return nil
	}
	// plain
	lp, err := s.readPlainLatest(ctx, id.Service)
	if err != nil { return err }
	if opErr := s.deleteObject(ctx, fmt.Sprintf("%s/%s.json", id.Service, id.Key)); opErr != nil { return opErr }
	delete(lp.Latest, id.Key)
	lblob, _ := json.Marshal(lp)
	if opErr := s.putObject(ctx, fmt.Sprintf("%s/__latest.json", id.Service), lblob); opErr != nil { return opErr }
	return nil
}

