	kf, err := s.readKeyFile(ctx, id)
	if err != nil { return nil, err }
	for _, e := range kf.Values {
		if e.Version == version {
			return &Secret{ID: id, Value: e.Value, Version: e.Version, LastModified: parseTimeStr(e.Created), User: e.CreatedBy}, nil
