func (s *S3Store) History(ctx context.Context, id SecretID) ([]*Secret, error) {
	kf, err := s.readKeyFile(ctx, id)
	if err != nil { return nil, err }
	vs := sortedVersions(kf)
	if len(vs) == 0 { return nil, ErrSecretNotFound }
	var out []*Secret
	for _, e := range vs {
		out = append(out, &Secret{ID: id, Value: e.Value, Version: e.Version, LastModified: parseTimeStr(e.Created), User: e.CreatedBy})
