	body, opErr := s.getObject(ctx, key)
	if opErr != nil {
		if isNoSuchKey(opErr) {
			return nil, ErrSecretNotFound
		}
		return nil, opErr
	}
	var kf s3KeyFile
	if err := json.Unmarshal(body, &kf); err != nil {
		return nil, err
	}
	if kf.Values == nil {
		kf.Values = map[string]s3ValueEntry{}
	}
	return &kf, nil
}

func latestEntry(kf *s3KeyFile) (s3ValueEntry, bool) {
	var best *s3ValueEntry
	for _, e := range kf.Values {
		if best == nil || e.Version > best.Version {
			ee := e
			best = &ee
		}
	}
	if best == nil { return s3ValueEntry{}, false }
	return *best, true
}
func sortedVersions(kf *s3KeyFile) []s3ValueEntry {
	var vs []s3ValueEntry
	for _, e := range kf.Values { vs = append(vs, e) }
	sort.Slice(vs, func(i,j int) bool { return vs[i].Version < vs[j].Version })
	return vs
}
func parseTimeStr(s string) time.Time {
	if s == "" { return time.Time{} }
	if t, err := time.Parse(time.RFC3339Nano, s); err == nil { return t }
	if t, err := time.Parse(time.RFC3339, s); err == nil { return t }
	return time.Time{}
}

func (s *S3Store) Read(ctx context.Context, id SecretID) (*Secret, error) {
	kf, err := s.readKeyFile(ctx, id)
	if err != nil { return nil, err }
	e, ok := latestEntry(kf)
	if !ok { return nil, ErrSecretNotFound }
	return &Secret{ID: id, Value: e.Value, Version: e.Version, LastModified: parseTimeStr(e.Created), User: e.CreatedBy}, nil
}
func (s *S3Store) ReadVersion(ctx context.Context, id SecretID, version int) (*Secret, error) {
	kf, err := s.readKeyFile(ctx, id)
	if err != nil { return nil, err }
	for _, e := range kf.Values {
		if e.Version == version {
			return &Secret{ID: id, Value: e.Value, Version: e.Version, LastModified: parseTimeStr(e.Created), User: e.CreatedBy}, nil
		}
	}
	return nil, ErrSecretNotFound
}
func (s *S3Store) History(ctx context.Context, id SecretID) ([]*Secret, error) {
	kf, err := s.readKeyFile(ctx, id)
	if err != nil { return nil, err }
	vs := sortedVersions(kf)
	if len(vs) == 0 { return nil, ErrSecretNotFound }
	var out []*Secret
	for _, e := range vs {
		out = append(out, &Secret{ID: id, Value: e.Value, Version: e.Version, LastModified: parseTimeStr(e.Created), User: e.CreatedBy})
	}
	return out, nil
}

// read plain latest
func (s *S3Store) readPlainLatest(ctx context.Context, service string) (s3LatestPlain, error) {
	key := fmt.Sprintf("%s/__latest.json", service)
	body, opErr := s.getObject(ctx, key)
	if opErr != nil {
		if isNoSuchKey(opErr) {
			return s3LatestPlain{Latest: map[string]string{}}, nil
		}
		return s3LatestPlain{}, opErr
	}
	var lp s3LatestPlain
	if err := json.Unmarshal(body, &lp); err != nil { return s3LatestPlain{}, err }
	if lp.Latest == nil { lp.Latest = map[string]string{} }
	return lp, nil
}

func (s *S3Store) ListRaw(ctx context.Context, service string) ([]*Secret, error) {
	if s.isKMS {
		files, err := s.listKMSLatestFilesFull(ctx, service)
		if err != nil { return nil, err }
		merged := map[string]string{}
		// files order as returned by ListObjects; merging overwriting later files? Original iterates files in list order.
		for _, f := range files {
			for k, e := range f.Data.Latest {
				merged[k] = e.Value
			}
		}
		var out []*Secret
		for k, v := range merged {
			out = append(out, &Secret{ID: SecretID{Service: service, Key: k}, Value: v})
		}
		sort.SliceStable(out, func(i,j int) bool { return out[i].ID.Key < out[j].ID.Key })
		return out, nil
	}
	lp, err := s.readPlainLatest(ctx, service)
	if err != nil { return nil, err }
	var out []*Secret
	for k, v := range lp.Latest {
		out = append(out, &Secret{ID: SecretID{Service: service, Key: k}, Value: v})
	}
	sort.SliceStable(out, func(i,j int) bool { return out[i].ID.Key < out[j].ID.Key })
	return out, nil
}

// listKMSLatestFilesFull handles pagination of ListObjectsV2 manually
func (s *S3Store) listKMSLatestFilesFull(ctx context.Context, service string) ([]kmsLatestFile, error) {
	keys, err := s.listObjectsKeys(ctx, service+"/__kms")
	if err != nil { return nil, err }
	var files []kmsLatestFile
	for _, k := range keys {
		body, opErr := s.getObject(ctx, k)
		if opErr != nil { return nil, opErr }
		var data s3LatestKMS
		if err := json.Unmarshal(body, &data); err != nil { return nil, err }
		if data.Latest == nil { data.Latest = map[string]s3LatestKMSEntry{} }
		alias := ""
		// deterministic alias extraction: sort keys
		var ks []string
		for key := range data.Latest { ks = append(ks, key) }
		sort.Strings(ks)
		if len(ks) > 0 { alias = data.Latest[ks[0]].KMSAlias }
		files = append(files, kmsLatestFile{Filename: k, Alias: alias, Data: data})
	}
	return files, nil
}

func (s *S3Store) List(ctx context.Context, service string, expand bool) ([]*Secret, error) {
	raw, err := s.ListRaw(ctx, service)
	if err != nil { return nil, err }
	var out []*Secret
	// raw is sorted by Key; for each, read key file for metadata
	for _, r := range raw {
		kf, err := s.readKeyFile(ctx, r.ID)
		if err != nil { return nil, err }
		e, ok := latestEntry(kf)
		if !ok { return nil, ErrSecretNotFound }
		sec := &Secret{ID: r.ID, Version: e.Version, LastModified: parseTimeStr(e.Created), User: e.CreatedBy, Value: e.Value}
		// For plain S3, latest raw value might differ from key file latest? Use e.value as in list -e earlier (matches)
		out = append(out, sec)
	}
	// ListRaw already sorted by key, which matches sort by ID string for same service
	return out, nil
}

func (s *S3Store) Write(ctx context.Context, id SecretID, value string) error {
	return s.write(ctx, id, value)
}
func (s *S3Store) WriteWithTags(ctx context.Context, id SecretID, value string, tags map[string]string) error {
	if s.isKMS {
		return errors.New("Not implemented for S3 KMS Store")
	}
	return errors.New("Not implemented for S3 Store")
}

func (s *S3Store) write(ctx context.Context, id SecretID, value string) error {
	// step1: read latest(s)
	var plainLatest s3LatestPlain
	var kmsFiles []kmsLatestFile
	var kmsCurrent *kmsLatestFile
	var kmsCurrentFilename string
	if s.isKMS {
		files, err := s.listKMSLatestFilesFull(ctx, id.Service)
		if err != nil { return err }
		kmsFiles = files
		kmsCurrentFilename = kmsLatestFilename(id.Service, s.kmsAlias)
		// find current file
		for i, f := range kmsFiles {
			if f.Filename == kmsCurrentFilename {
				kmsCurrent = &kmsFiles[i]
				break
			}
		}
		if kmsCurrent == nil {
			// create empty placeholder
			kmsCurrent = &kmsLatestFile{Filename: kmsCurrentFilename, Alias: s.kmsAlias, Data: s3LatestKMS{Latest: map[string]s3LatestKMSEntry{}}}
		}
	} else {
		lp, err := s.readPlainLatest(ctx, id.Service)
		if err != nil { return err }
		plainLatest = lp
	}
	// step2: read key file
	kf, err := s.readKeyFile(ctx, id)
	if err != nil {
		if errors.Is(err, ErrSecretNotFound) {
			kf = &s3KeyFile{Service: id.Service, Key: id.String(), Values: map[string]s3ValueEntry{}}
		} else {
			return err
		}
	}
	// user
	userArn, opErr := s.cfg.getCallerIdentity(ctx)
	if opErr != nil { return opErr }
	nowStr := time.Now().UTC().Format(time.RFC3339Nano)
	newVersion := 1
	if e, ok := latestEntry(kf); ok {
		newVersion = e.Version + 1
	}
	if kf.Values == nil { kf.Values = map[string]s3ValueEntry{} }
	kf.Service = id.Service
	kf.Key = id.String()
	kf.Values[strconv.Itoa(newVersion)] = s3ValueEntry{Created: nowStr, CreatedBy: userArn, Version: newVersion, Value: value}
	blob, _ := json.Marshal(kf)
	if opErr := s.putObject(ctx, fmt.Sprintf("%s/%s.json", id.Service, id.Key), blob); opErr != nil { return opErr }
	// update latest
	if s.isKMS {
		if kmsCurrent.Data.Latest == nil { kmsCurrent.Data.Latest = map[string]s3LatestKMSEntry{} }
		kmsCurrent.Data.Latest[id.Key] = s3LatestKMSEntry{Version: newVersion, Value: value, KMSAlias: s.kmsAlias}
		lblob, _ := json.Marshal(kmsCurrent.Data)
		if opErr := s.putObjectWithAlias(ctx, kmsCurrentFilename, lblob, s.kmsAlias); opErr != nil { return opErr }
	} else {
		if plainLatest.Latest == nil { plainLatest.Latest = map[string]string{} }
		plainLatest.Latest[id.Key] = value
		lblob, _ := json.Marshal(plainLatest)
		if opErr := s.putObject(ctx, fmt.Sprintf("%s/__latest.json", id.Service), lblob); opErr != nil { return opErr }
	}
	return nil
}

func (s *S3Store) Delete(ctx context.Context, id SecretID) error {
	if s.isKMS {
		files, err := s.listKMSLatestFilesFull(ctx, id.Service)
		if err != nil { return err }
		// delete object
		if opErr := s.deleteObject(ctx, fmt.Sprintf("%s/%s.json", id.Service, id.Key)); opErr != nil { return opErr }
		// find file(s) containing key, update each? Original updated only the file that contained key (one). If multiple, maybe ... We'll update all containing to be safe? But original test with single file updated that one.
		// Determine first containing file
		updated := false
		for _, f := range files {
			if _, ok := f.Data.Latest[id.Key]; ok {
				delete(f.Data.Latest, id.Key)
				lblob, _ := json.Marshal(f.Data)
				alias := f.Alias
				if alias == "" { alias = s.kmsAlias }
				if opErr := s.putObjectWithAlias(ctx, f.Filename, lblob, alias); opErr != nil { return opErr }
				updated = true
				break
			}
		}
		if !updated {
			// No file contains key: original behaviour? For plain it created an empty latest. For KMS unknown. It may not put any.
			// But early delete missing test for plain created latest. For KMS, we leave as is.
		}
		return nil
	}
	// plain
	lp, err := s.readPlainLatest(ctx, id.Service)
	if err != nil { return err }
	if opErr := s.deleteObject(ctx, fmt.Sprintf("%s/%s.json", id.Service, id.Key)); opErr != nil { return opErr }
	delete(lp.Latest, id.Key)
	lblob, _ := json.Marshal(lp)
	if opErr := s.putObject(ctx, fmt.Sprintf("%s/__latest.json", id.Service), lblob); opErr != nil { return opErr }
	return nil
}

func (s *S3Store) ListServices(ctx context.Context, prefix string) ([]string, error) {
	if s.isKMS {
		return nil, errors.New("S3KMS Backend is experimental and does not implement this command")
	}
	return nil, errors.New("S3 Backend is experimental and does not implement this command")
}
func (s *S3Store) ReadTags(ctx context.Context, id SecretID) ([]Tag, error) {
	return nil, errors.New("Not implemented for S3 Store")
}
func (s *S3Store) WriteTags(ctx context.Context, id SecretID, tags map[string]string, deleteOther bool, tagsSlice []Tag) error {
	return errors.New("Not implemented for S3 Store")
}
func (s *S3Store) DeleteTags(ctx context.Context, id SecretID, tagKeys []string) error {
	return errors.New("Not implemented for S3 Store")
}
EOF
echo ok"}

