	// Use cmd.Flags().Changed which checks inherited?
	return cmd.Flags().Changed(name) || cmd.InheritedFlags().Changed(name) || cmd.PersistentFlags().Changed(name)
}

func resolveBackend(cmd *cobra.Command) string {
	if flagChanged(cmd, "backend") {
		return globalBackend
	}
	if v := os.Getenv("CHAMBER_SECRET_BACKEND"); v != "" {
		return v
	}
	return globalBackend
}
func resolveRetries(cmd *cobra.Command) (int, error) {
	if cmd != nil && flagChanged(cmd, "retries") {
		return globalRetries, nil
	}
	if v := os.Getenv("CHAMBER_RETRIES"); v != "" {
		i, err := strconv.Atoi(v)
		if err != nil {
			return 0, fmt.Errorf("Cannot parse $CHAMBER_RETRIES to an integer.")
		}
		return i, nil
	}
	return globalRetries, nil
}
func resolveBucket(cmd *cobra.Command) string {
	if cmd != nil && flagChanged(cmd, "backend-s3-bucket") {
		return globalBackendS3Bucket
	}
	if v := os.Getenv("CHAMBER_S3_BUCKET"); v != "" {
