	}
	if v := os.Getenv("CHAMBER_KMS_KEY_ALIAS"); v != "" {
		return v
	}
	return globalKmsKeyAlias
}
func normalizeKMSAlias(a string) string {
	if strings.HasPrefix(a, "alias/") {
		return a
	}
	return "alias/" + a
}

func getSecretStore(ctx context.Context, cmd *cobra.Command) (Store, error) {
	// retries parsing first (before backend checks), as observed
	retries, err := resolveRetries(cmd)
	if err != nil {
		return nil, err
	}
	backendRaw := resolveBackend(cmd)
	backend := strings.ToUpper(backendRaw)
	switch backend {
	case "NULL":
		return &NullStore{}, nil
	case "SSM":
		if globalKmsKeyAlias != "alias/parameter_store_key" {
			return nil, fmt.Errorf("Unable to use --kms-key-alias with this backend. Use CHAMBER_KMS_KEY_ALIAS instead.")
		}
		if globalRetryMode != "standard" && globalRetryMode != "adaptive" {
			return nil, fmt.Errorf("Invalid retry mode %s", globalRetryMode)
		}
		cfg, err := loadAWSConfig(retries)
		if err != nil {
			return nil, err
		}
		// SSM KMS key: from env if present (LookupEnv), else default
		kmsAlias := "parameter_store_key"
		if v, ok := os.LookupEnv("CHAMBER_KMS_KEY_ALIAS"); ok {
			kmsAlias = v
		}
		kmsKeyId := "alias/" + strings.TrimPrefix(kmsAlias, "alias/")
		// Note: if kmsAlias already had alias/ prefix, TrimPrefix removed it, then add back.
		// If kmsAlias is "alias/custom" -> "alias/custom"; if "custom" -> "alias/custom"; if "" -> "alias/"
		return &SSMStore{cfg: cfg, kmsKeyId: kmsKeyId}, nil
	case "SECRETSMANAGER":
		cfg, err := loadAWSConfig(retries)
		if err != nil {
			return nil, err
		}
		return &SecretsManagerStore{cfg: cfg}, nil
	case "S3":
		if globalKmsKeyAlias != "alias/parameter_store_key" {
			return nil, fmt.Errorf("Unable to use --kms-key-alias with this backend.")
		}
		bucket := resolveBucket(cmd)
		if bucket == "" {
			return nil, fmt.Errorf("Must set bucket for s3 backend")
		}
		cfg, err := loadAWSConfig(retries)
		if err != nil {
			return nil, err
		}
		return &S3Store{cfg: cfg, bucket: bucket, isKMS: false}, nil
	case "S3-KMS":
		bucket := resolveBucket(cmd)
		if bucket == "" {
			return nil, fmt.Errorf("Must set bucket for s3 backend")
		}
		cfg, err := loadAWSConfig(retries)
		if err != nil {
			return nil, err
		}
		effective := resolveKmsFlagEffective(cmd)
		alias := normalizeKMSAlias(effective)
		return &S3Store{cfg: cfg, bucket: bucket, isKMS: true, kmsAlias: alias}, nil
	default:
		return nil, fmt.Errorf("invalid backend `%s`", backend)
	}
}

func getStoreOrErr(ctx context.Context, cmd *cobra.Command) (Store, error) {
	store, err := getSecretStore(ctx, cmd)
	if err != nil {
		return nil, fmt.Errorf("Failed to get secret store: %w", err)
	}
	return store, nil
}

