var deleteExactKey bool

func newDeleteCmd() *cobra.Command {
	c := &cobra.Command{
		Use:   "delete <service> <key>",
		Short: "Delete a secret, including all versions",
		Args:  cobra.ExactArgs(2),
		RunE: func(cmd *cobra.Command, args []string) error {
			ctx := context.Background()
			// service parse
			svc, err := parseService(args[0], false)
			if err != nil {
				return fmt.Errorf("Failed to validate service: %w", err)
			}
			var key string
			if deleteExactKey {
				key = args[1]
				if err := validateKeyName(key); err != nil {
					return fmt.Errorf("Failed to validate key: %w", err)
				}
			} else {
				key = strings.ToLower(args[1])
				if err := validateKeyName(key); err != nil {
					return fmt.Errorf("Failed to validate key: %w", err)
				}
			}
			id := SecretID{Service: svc, Key: key}
			store, err := getStoreOrErr(ctx, cmd)
			if err != nil {
				return err
			}
			if err := store.Delete(ctx, id); err != nil {
				return err
			}
			return nil
		},
	}
	c.Flags().BoolVar(&deleteExactKey, "exact-key", false, "Prevent normalization of the provided key in order to delete any keys that match the exact provided casing.")
	return c
}

// LIST
var listExpand bool
var listSortTime bool
var listSortUser bool
var listSortVersion bool

func newListCmd() *cobra.Command {
	c := &cobra.Command{
		Use:   "list <service>",
		Short: "List the secrets set for a service",
		Args:  cobra.ExactArgs(1),
		RunE: func(cmd *cobra.Command, args []string) error {
			ctx := context.Background()
			svc, err := parseService(args[0], true)
			if err != nil {
				return fmt.Errorf("Failed to validate service: %w", err)
			}
			store, err := getStoreOrErr(ctx, cmd)
			if err != nil {
				return err
			}
			secrets, err := store.List(ctx, svc, listExpand)
			if err != nil {
				return fmt.Errorf("Failed to list store contents: %w", err)
			}
			// sorting: stable sorts applied in order time, user, version
			if listSortTime {
				sort.SliceStable(secrets, func(i, j int) bool { return secrets[i].LastModified.Before(secrets[j].LastModified) })
			}
			if listSortUser {
				sort.SliceStable(secrets, func(i, j int) bool { return secrets[i].User < secrets[j].User })
			}
			if listSortVersion {
				sort.SliceStable(secrets, func(i, j int) bool { return secrets[i].Version < secrets[j].Version })
			}
			w := tableWriter()
			if listExpand {
				fmt.Fprintln(w, "Key\tVersion\tLastModified\tUser\tValue")
				for _, s := range secrets {
					fmt.Fprintf(w, "%s\t%d\t%s\t%s\t%s\n", s.ID.Key, s.Version, formatTime(s.LastModified), s.User, s.Value)
				}
			} else {
				fmt.Fprintln(w, "Key\tVersion\tLastModified\tUser")
				for _, s := range secrets {
					fmt.Fprintf(w, "%s\t%d\t%s\t%s\n", s.ID.Key, s.Version, formatTime(s.LastModified), s.User)
				}
			}
			w.Flush()
			return nil
		},
	}
	c.Flags().BoolVarP(&listExpand, "expand", "e", false, "Expand parameter list with values")
	c.Flags().BoolVarP(&listSortTime, "time", "t", false, "Sort by modified time")
	c.Flags().BoolVarP(&listSortUser, "user", "u", false, "Sort by user")
	c.Flags().BoolVarP(&listSortVersion, "version", "v", false, "Sort by version")
	return c
}

// LIST-SERVICES
var listServicesSecrets bool

func newListServicesCmd() *cobra.Command {
	c := &cobra.Command{
		Use:   "list-services <service>",
		Short: "List services",
		Args:  cobra.ArbitraryArgs,
		RunE: func(cmd *cobra.Command, args []string) error {
			ctx := context.Background()
			prefix := ""
			if len(args) > 0 {
				prefix = strings.ToLower(args[0])
			}
			store, err := getStoreOrErr(ctx, cmd)
			if err != nil {
				return err
			}
			// For SSM-like stores, ListServices returns full secret names (sorted)
			names, err := store.ListServices(ctx, prefix)
			if err != nil {
				return fmt.Errorf("Failed to list store contents: %w", err)
			}
			// names handling depends on backend type: For Null, names is empty slice.
			// Determine output lines:
			// If store is SSM, names are full names. Other stores that implement ListServices (null) return empty/names already as service lines?
			// Our Store contract: ListServices returns full secret names for SSM, empty for Null, error for others.
			// Convert.
			w := tableWriter()
			fmt.Fprintln(w, "Service")
			if listServicesSecrets {
				// names already sorted full names
				for _, n := range names {
					fmt.Fprintln(w, n)
				}
			} else {
				// If names appear to be full secret names (start with "/"), extract services. If they are plain service names, print them.
				// SSM case: extract
				servicesMap := map[string]bool{}
				var services []string
				for _, n := range names {
					if strings.HasPrefix(n, "/") {
						id, ok := parseSecretIDFromFullName(n)
						if !ok { continue }
						svc := id.Service
						if !servicesMap[svc] {
							servicesMap[svc] = true
							services = append(services, svc)
						}
					} else {
						if !servicesMap[n] {
							servicesMap[n] = true
							services = append(services, n)
						}
					}
				}
				sort.Strings(services)
				for _, s := range services {
					fmt.Fprintln(w, s)
				}
			}
			w.Flush()
			return nil
		},
	}
	c.Flags().BoolVarP(&listServicesSecrets, "secrets", "s", false, "Include secret names in the list")
	return c
}

