		Run: func(cmd *cobra.Command, args []string) {
			fmt.Println("chamber dev")
		},
	}
}

// WRITE
var writeSingleline bool
var writeSkipUnchanged bool
var writeTags map[string]string

func newWriteCmd() *cobra.Command {
	c := &cobra.Command{
		Use:   "write <service> <key> [--] <value|->",
		Short: "write a secret",
		Args:  cobra.ExactArgs(3),
		RunE: func(cmd *cobra.Command, args []string) error {
			return runWrite(cmd, args)
		},
	}
	c.Flags().BoolVarP(&writeSingleline, "singleline", "s", false, "Insert single line parameter (end with \\n)")
	c.Flags().BoolVar(&writeSkipUnchanged, "skip-unchanged", false, "Skip writing secret if value is unchanged")
	c.Flags().StringToStringVarP(&writeTags, "tags", "t", map[string]string{}, "Add tags to the secret; new secrets only")
	return c
}

func runWrite(cmd *cobra.Command, args []string) error {
	ctx := context.Background()
	id, err := parseSecretID(args[0], args[1])
	if err != nil {
		return err
	}
	// id already handled service/key validation; need match error precedence: service first, then key.
	// parseSecretID does that.
	value := args[2]
	if value == "-" {
		if writeSingleline {
			reader := bufio.NewReader(os.Stdin)
			line, err := reader.ReadString('\n')
			if err != nil {
				return err
			}
			value = strings.TrimSuffix(line, "\n")
		} else {
			data, err := io.ReadAll(os.Stdin)
			if err != nil {
				return err
			}
			value = string(data)
		}
	}
	store, err := getStoreOrErr(ctx, cmd)
	if err != nil {
		return err
	}
	if writeSkipUnchanged {
		if existing, err := store.Read(ctx, id); err == nil {
			if existing.Value == value {
				return nil
			}
		}
	}
	if len(writeTags) > 0 {
		return store.WriteWithTags(ctx, id, value, writeTags)
	}
	return store.Write(ctx, id, value)
}

// READ
var readQuiet bool
var readVersion int

func newReadCmd() *cobra.Command {
	c := &cobra.Command{
		Use:   "read <service> <key>",
		Short: "Read a specific secret from the parameter store",
		Args:  cobra.ExactArgs(2),
		RunE: func(cmd *cobra.Command, args []string) error {
			ctx := context.Background()
			id, err := parseSecretID(args[0], args[1])
			if err != nil {
				return err
			}
			store, err := getStoreOrErr(ctx, cmd)
			if err != nil {
				return err
			}
			var secret *Secret
			if readVersion == -1 {
