			// service parse
			svc, err := parseService(args[0], false)
			if err != nil {
				return fmt.Errorf("Failed to validate service: %w", err)
			}
			var key string
			if deleteExactKey {
				key = args[1]
				if err := validateKeyName(key); err != nil {
					return fmt.Errorf("Failed to validate key: %w", err)
