			params[key] = s.Value
		}
	}
	var out io.Writer = os.Stdout
	var file *os.File
	if exportOutputFile != "" {
		f, err := os.Create(exportOutputFile)
		if err != nil {
			return fmt.Errorf("Failed to open output file for writing: %w", err)
		}
		file = f
		out = f
		defer f.Close()
	}
	_ = file
	// format (case-insensitive)
	formatLower := strings.ToLower(exportFormat)
	switch formatLower {
	case "json":
		data, err := json.Marshal(params)
		if err != nil { return fmt.Errorf("Unable to export parameters: %w", err) }
		fmt.Fprintln(out, string(data))
	case "yaml":
		// yaml Marshal of map
		data, err := yaml.Marshal(params)
		if err != nil { return fmt.Errorf("Unable to export parameters: %w", err) }
		fmt.Fprint(out, string(data))
	case "java-properties":
		keys := sortedKeys(params)
		for _, k := range keys {
			fmt.Fprintf(out, "%s = %s\n", k, escapeJavaProperties(params[k]))
		}
	case "csv":
		keys := sortedKeys(params)
		w := csv.NewWriter(out)
		w.Comma = ','
		for _, k := range keys {
			_ = w.Write([]string{k, params[k]})
		}
		w.Flush()
	case "tsv":
		keys := sortedKeys(params)
		w := csv.NewWriter(out)
		w.Comma = '\t'
		for _, k := range keys {
			_ = w.Write([]string{k, params[k]})
		}
		w.Flush()
	case "dotenv":
		keys := sortedKeys(params)
		for _, k := range keys {
			name := envVarName(k, false)
			fmt.Fprintf(out, "%s=\"%s\"\n", name, escapeDoubleQuoted(params[k]))
		}
	case "tfvars":
		keys := sortedKeys(params)
		for _, k := range keys {
			name := strings.ReplaceAll(strings.ReplaceAll(k, "-", "_"), ".", "_")
			fmt.Fprintf(out, "%s = \"%s\"\n", name, escapeDoubleQuoted(params[k]))
		}
	default:
		return fmt.Errorf("Unable to export parameters: Unsupported export format: %s", exportFormat)
	}
	return nil
}

func sortedKeys(m map[string]string) []string {
	var keys []string
	for k := range m { keys = append(keys, k) }
	sort.Strings(keys)
	return keys
}
func escapeJavaProperties(v string) string {
	r := strings.NewReplacer(
		`\`, `\\`,
		"\n", `\n`,
		"\r", `\r`,
		"\t", `\t`,
	)
	return r.Replace(v)
}

// FIND
var findByValue bool

func newFindCmd() *cobra.Command {
	c := &cobra.Command{
		Use:   "find <secret name>",
		Short: "Find the given secret across all services",
		Args:  cobra.ExactArgs(1),
		RunE: func(cmd *cobra.Command, args []string) error {
			ctx := context.Background()
			store, err := getStoreOrErr(ctx, cmd)
			if err != nil {
				return err
			}
			needle := args[0]
			// ListServices with prefix "" returns full names for SSM, empty for null, error for others
