			if err != nil {
				return fmt.Errorf("Failed to list store contents: %w", err)
			}
			w := tableWriter()
			if findByValue {
				fmt.Fprintln(w, "Service\tKey")
				// Build services set from names (map iteration like original)
				servicesSet := map[string]bool{}
				for _, n := range names {
					if strings.HasPrefix(n, "/") {
						if id, ok := parseSecretIDFromFullName(n); ok {
							servicesSet[id.Service] = true
						}
					} else {
						servicesSet[n] = true
					}
				}
				for svc := range servicesSet {
					secrets, err := store.List(ctx, svc, true)
					if err != nil {
						return fmt.Errorf("Failed to list store contents: %w", err)
					}
					for _, s := range secrets {
						if s.Value == needle {
							fmt.Fprintf(w, "%s\t%s\n", svc, s.ID.Key)
						}
					}
				}
				w.Flush()
				return nil
			}
			fmt.Fprintln(w, "Service")
			servicesSet := map[string]bool{}
			for _, n := range names {
				if strings.HasPrefix(n, "/") {
					if id, ok := parseSecretIDFromFullName(n); ok {
						if id.Key == needle {
							servicesSet[id.Service] = true
						}
					}
				}
			}
			var services []string
			for svc := range servicesSet { services = append(services, svc) }
			sort.Strings(services)
			for _, svc := range services {
				fmt.Fprintln(w, svc)
			}
			w.Flush()
			return nil
		},
	}
	c.Flags().BoolVarP(&findByValue, "by-value", "v", false, "Find parameters by value")
