			if execStrict {
				if parentVal, ok := parentMap[envKey]; ok {
					if parentVal != execStrictValue {
						return fmt.Errorf("parent env has %s, but was expecting value `%s`, not `%s`", envKey, execStrictValue, parentVal)
					}
					// inject
					if _, exists := injected[envKey]; !exists { injectedOrder = append(injectedOrder, envKey) }
					injected[envKey] = s.Value
					resultEnv.setSecret(envKey, s.Value)
				} else {
					// do not inject
				}
			} else {
				// non strict
				if _, exists := resultEnv.get(envKey); exists {
					// check if this exists from parent or previous service - warning printed regardless of whether it was parent or previous?
					// Original warning: "warning: service %s overwriting environment variable %s"
					// It was printed when overwriting parent or previous service.
					fmt.Fprintf(os.Stderr, "warning: service %s overwriting environment variable %s\n", svc, envKey)
				}
				if _, exists := injected[envKey]; !exists { injectedOrder = append(injectedOrder, envKey) }
				injected[envKey] = s.Value
				resultEnv.setSecret(envKey, s.Value)
			}
		}
	}
	if execStrict {
		// check unfilled parent placeholders
		// Iterate parent entries in order (original map iteration may differ)
		for _, en := range parent.entries {
			if en.Value == execStrictValue {
				normalized := envVarName(en.Key, false) // envVarName uppercases and replaces - .
				// But normalization check: key is not normalized if key != normalized form (where normalized form for a key is uppercase+replace?)
				// For key like "a-b", normalized is "A_B"; en.Key != that.
				if en.Key != normalized {
					return fmt.Errorf("parent env has key `%s` with expected value `%s`, but key is not normalized like `%s`, so would never get substituted", en.Key, execStrictValue, normalized)
				}
				if _, ok := injected[en.Key]; !ok {
					return fmt.Errorf("parent env was expecting %s=%s, but was not in store", en.Key, execStrictValue)
				}
			}
		}
	}
	var finalEnv *Environ
	if execPristine {
		finalEnv = &Environ{index: map[string]int{}}
		// In strict mode, only injected; in non-strict, all secrets injected (injectedOrder)
		// injectedOrder reflects order secrets were processed (ListRaw sorted etc)
		for _, k := range injectedOrder {
			finalEnv.setSecret(k, injected[k])
		}
	} else {
		finalEnv = resultEnv
	}
	if globalVerbose {
		// DEBUG slog
		envStrings := finalEnv.strings()
		// slog default handler to stderr with time in UTC? Go slog uses local time; set via environment? Original shows Z (UTC) because local is UTC in test env.
		// Use default slog
		slog.Debug(fmt.Sprintf("info: With environment %s\n", strings.Join(envStrings, ",")))
	}
	// exec command
	if len(commandArgs) == 0 {
		return fmt.Errorf("must specify command to run. See usage: requires at least 1 arg(s), only received 0")
	}
	binary, err := exec.LookPath(commandArgs[0])
	if err != nil {
		return err
	}
	// Use syscall.Exec to replace process (matches signal behaviour)
	err = syscall.Exec(binary, commandArgs, finalEnv.strings())
	if err != nil {
		return err
	}
	return nil
}

var _ = sort.Strings
EOF
echo ok"}

