				return fmt.Errorf("must specify command to run. See usage: requires at least 1 arg(s), only received 0")
			}
			// Also need check services present (already) and command present
			return nil
		},
		RunE: func(cmd *cobra.Command, args []string) error {
			return runExec(cmd, args)
		},
	}
	c.Flags().BoolVar(&execPristine, "pristine", false, "only use variables retrieved from the backend; do not inherit existing environment variables")
	c.Flags().BoolVar(&execStrict, "strict", false, "enable strict mode:\nonly inject secrets for which there is a corresponding env var with value\n<strict-value>, and fail if there are any env vars with that value missing\nfrom secrets")
	c.Flags().StringVar(&execStrictValue, "strict-value", "chamberme", "value to expect in --strict mode")
	return c
}

// Environ handling
type environEntry struct {
	Key string
	Value string
}
type Environ struct {
	entries []environEntry // parent entries in order, plus appended secrets (with overwritten removed)
	// for quick lookup
	index map[string]int
}
func newEnvironFromOS() *Environ {
	e := &Environ{index: map[string]int{}}
	for _, kv := range os.Environ() {
		k, v, _ := strings.Cut(kv, "=")
		e.setRaw(k, v, false)
	}
	return e
}
func (e *Environ) setRaw(k, v string, move bool) {
	if idx, ok := e.index[k]; ok {
		// remove existing if move? We'll implement delete then append when set by secret (handled by caller)
		e.entries[idx].Value = v
		return
	}
	e.index[k] = len(e.entries)
	e.entries = append(e.entries, environEntry{k, v})
}
func (e *Environ) deleteKey(k string) {
	idx, ok := e.index[k]
	if !ok { return }
	e.entries = append(e.entries[:idx], e.entries[idx+1:]...)
	// rebuild index
	e.index = map[string]int{}
	for i, en := range e.entries { e.index[en.Key] = i }
}
func (e *Environ) get(k string) (string, bool) {
	if idx, ok := e.index[k]; ok { return e.entries[idx].Value, true }
	return "", false
}
func (e *Environ) setSecret(k, v string) {
	// if exists, delete then append (to mimic moving to end-ish). Original ordering random, this is acceptable.
	if _, ok := e.index[k]; ok {
		e.deleteKey(k)
	}
	e.index[k] = len(e.entries)
	e.entries = append(e.entries, environEntry{k, v})
}
func (e *Environ) strings() []string {
	var out []string
	for _, en := range e.entries {
		out = append(out, en.Key+"="+en.Value)
	}
	return out
}

func runExec(cmd *cobra.Command, args []string) error {
	ctx := context.Background()
	dash := cmd.Flags().ArgsLenAtDash()
	servicesRaw := args[:dash]
	commandArgs := args[dash:]
	// validate services (colon variant)
	var services []string
	for _, rs := range servicesRaw {
		svc, err := parseService(rs, true)
		if err != nil {
			return fmt.Errorf("Failed to validate service: %w", err)
		}
		services = append(services, svc)
	}
	store, err := getStoreOrErr(ctx, cmd)
	if err != nil {
		return err
	}
	// Load environ
	parent := newEnvironFromOS()
	// snapshot of parent for strict checks
	parentMap := map[string]string{}
	for _, en := range parent.entries { parentMap[en.Key] = en.Value }
	resultEnv := newEnvironFromOS()
	// Track substituted keys in strict mode and injected secrets for pristine
	injected := map[string]string{}
	var injectedOrder []string
	// For each service
	for _, svc := range services {
		secrets, err := store.ListRaw(ctx, svc)
		if err != nil {
			return fmt.Errorf("Failed to list store contents: %w", err)
		}
		// Iterate secrets: Original iterates a map (random). Our ListRaw returns sorted slice; acceptable.
		// To mimic map iteration flavour, we iterate as-is.
		for _, s := range secrets {
			envKey := envVarName(s.ID.Key, false)
			if execStrict {
				if parentVal, ok := parentMap[envKey]; ok {
					if parentVal != execStrictValue {
						return fmt.Errorf("parent env has %s, but was expecting value `%s`, not `%s`", envKey, execStrictValue, parentVal)
					}
					// inject
					if _, exists := injected[envKey]; !exists { injectedOrder = append(injectedOrder, envKey) }
					injected[envKey] = s.Value
					resultEnv.setSecret(envKey, s.Value)
				} else {
					// do not inject
				}
			} else {
				// non strict
				if _, exists := resultEnv.get(envKey); exists {
					// check if this exists from parent or previous service - warning printed regardless of whether it was parent or previous?
					// Original warning: "warning: service %s overwriting environment variable %s"
					// It was printed when overwriting parent or previous service.
					fmt.Fprintf(os.Stderr, "warning: service %s overwriting environment variable %s\n", svc, envKey)
				}
				if _, exists := injected[envKey]; !exists { injectedOrder = append(injectedOrder, envKey) }
				injected[envKey] = s.Value
				resultEnv.setSecret(envKey, s.Value)
			}
		}
	}
	if execStrict {
		// check unfilled parent placeholders
		// Iterate parent entries in order (original map iteration may differ)
		for _, en := range parent.entries {
			if en.Value == execStrictValue {
				normalized := envVarName(en.Key, false) // envVarName uppercases and replaces - .
				// But normalization check: key is not normalized if key != normalized form (where normalized form for a key is uppercase+replace?)
				// For key like "a-b", normalized is "A_B"; en.Key != that.
				if en.Key != normalized {
					return fmt.Errorf("parent env has key `%s` with expected value `%s`, but key is not normalized like `%s`, so would never get substituted", en.Key, execStrictValue, normalized)
				}
				if _, ok := injected[en.Key]; !ok {
					return fmt.Errorf("parent env was expecting %s=%s, but was not in store", en.Key, execStrictValue)
				}
			}
		}
	}
	var finalEnv *Environ
	if execPristine {
		finalEnv = &Environ{index: map[string]int{}}
		// In strict mode, only injected; in non-strict, all secrets injected (injectedOrder)
		// injectedOrder reflects order secrets were processed (ListRaw sorted etc)
		for _, k := range injectedOrder {
			finalEnv.setSecret(k, injected[k])
		}
	} else {
		finalEnv = resultEnv
	}
	if globalVerbose {
		// DEBUG slog
		envStrings := finalEnv.strings()
		// slog default handler to stderr with time in UTC? Go slog uses local time; set via environment? Original shows Z (UTC) because local is UTC in test env.
		// Use default slog
		slog.Debug(fmt.Sprintf("info: With environment %s\n", strings.Join(envStrings, ",")))
	}
	// exec command
	if len(commandArgs) == 0 {
		return fmt.Errorf("must specify command to run. See usage: requires at least 1 arg(s), only received 0")
	}
	binary, err := exec.LookPath(commandArgs[0])
	if err != nil {
		return err
	}
	// Use syscall.Exec to replace process (matches signal behaviour)
	err = syscall.Exec(binary, commandArgs, finalEnv.strings())
	if err != nil {
		return err
	}
	return nil
}

var _ = sort.Strings
EOF
echo ok"}

