			if err != nil { return err }
			// parse tags
			tagsMap := map[string]string{}
			var tagsSlice []Tag
			// parse each arg, keep order of first (?) For duplicates, original output showed only last value.
			// We'll parse sequentially, dedup by key preserving position of first occurrence? But output for duplicates a=1 a=2 showed a 2 at (only) place.
			for _, raw := range args[2:] {
				idx := strings.Index(raw, "=")
				if idx < 0 {
					return fmt.Errorf("Failed to parse tag %s: tag must be in the form key=value", raw)
				}
				k := raw[:idx]
				v := raw[idx+1:]
				if _, exists := tagsMap[k]; exists {
					// replace slice entry
					for i, t := range tagsSlice {
						if t.Key == k { tagsSlice[i].Value = v; break }
					}
					tagsMap[k] = v
				} else {
					tagsMap[k] = v
					tagsSlice = append(tagsSlice, Tag{Key: k, Value: v})
				}
			}
			// validate tags (iterate slice for deterministic first error)
			for _, t := range tagsSlice {
				if err := validateTagKey(t.Key); err != nil {
					return fmt.Errorf("Failed to validate tag with key %s: %w", t.Key, err)
				}
				if err := validateTagValue(t.Value); err != nil {
					return fmt.Errorf("Failed to validate tag with key %s: %w", t.Key, err)
				}
			}
			store, err := getStoreOrErr(ctx, cmd)
			if err != nil { return err }
			if err := store.WriteTags(ctx, id, tagsMap, tagWriteDeleteOther, tagsSlice); err != nil {
				return fmt.Errorf("Failed to write tags: %w", err)
			}
			w := tableWriter()
			fmt.Fprintln(w, "Key\tValue")
			for _, t := range tagsSlice {
				fmt.Fprintf(w, "%s\t%s\n", t.Key, t.Value)
			}
			w.Flush()
			return nil
		},
	}
	c.Flags().BoolVar(&tagWriteDeleteOther, "delete-other-tags", false, "Delete tags not specified in the command")
