func runImport(cmd *cobra.Command, args []string) error {
	ctx := context.Background()
	svc, err := parseService(args[0], false)
	if err != nil {
		return fmt.Errorf("Failed to validate service: %w", err)
	}
	source := args[1]
	var data []byte
	if source == "-" {
		b, err := io.ReadAll(os.Stdin)
		if err != nil { return err }
		data = b
	} else {
		f, err := os.Open(source)
		if err != nil {
			return fmt.Errorf("Failed to open file: %w", err)
		}
		defer f.Close()
		b, err := io.ReadAll(f)
		if err != nil { return err }
		data = b
	}
	secretsMap, err := parseImportData(data)
	if err != nil {
		return fmt.Errorf("Failed to decode input as json: %w", err)
	}
	// get store after decoding? Original: with bogus backend and valid data, error was Failed to get secret store before writing.
	// With empty data decode error, it errored before backend check (we already decoded). For valid empty map, bogus would give store error? Need test later.
	// Our flow: get store now.
	store, err := getStoreOrErr(ctx, cmd)
	if err != nil { return err }
	// Import order: iterate map (Go map random)
