			switch root.Tag {
			case "!!str":
				kindName = "string"
			case "!!int":
				kindName = "int"
			case "!!float":
				kindName = "float"
			case "!!bool":
				kindName = "boolean"
			default:
				kindName = "string"
			}
		case yaml.DocumentNode:
			kindName = "string"
		default:
			kindName = "string"
		}
		return nil, goccyError(data, root.Line, root.Column, fmt.Sprintf("%s was used where mapping is expected", kindName))
	}
	result := map[string]string{}
	seen := map[string][2]int{} // key -> [line,col] of first definition
	for i := 0; i < len(root.Content); i += 2 {
		keyNode := root.Content[i]
		var valNode *yaml.Node
		if i+1 < len(root.Content) {
			valNode = root.Content[i+1]
		}
		keyStr, err := convertKeyNode(data, keyNode)
		if err != nil {
			return nil, err
		}
