			// goccy duplicate error: [line:col] mapping key "a" already defined at [line:col]
			msg := fmt.Sprintf("mapping key %q already defined at [%d:%d]", keyStr, prev[0], prev[1])
			return nil, goccyError(data, keyNode.Line, keyNode.Column, msg)
		}
		seen[keyStr] = [2]int{keyNode.Line, keyNode.Column}
		if valNode == nil {
			result[keyStr] = ""
			continue
		}
		valStr, err := convertValueNode(data, valNode)
		if err != nil {
			return nil, err
		}
		result[keyStr] = valStr
