func convertKeyNode(data []byte, n *yaml.Node) (string, error) {
	if n.Kind != yaml.ScalarNode {
		// complex key: approximate
		return "", goccyError(data, n.Line, n.Column, "cannot unmarshal something into Go value of type string")
	}
	switch n.Tag {
	case "!!str":
		return n.Value, nil
	case "!!int":
