		v, err := parseYAMLInt(n.Value)
		if err != nil {
			return n.Value, nil
		}
		return strconv.FormatInt(v, 10), nil
	case "!!bool":
		return "", goccyError(data, n.Line, n.Column, `cannot convert "bool" type to "string" type`)
	case "!!float":
		return "", goccyError(data, n.Line, n.Column, `cannot convert "float64" type to "string" type`)
	case "!!null":
		// ?
		return "", nil
	default:
		return n.Value, nil
	}
}

func convertValueNode(data []byte, n *yaml.Node) (string, error) {
	switch n.Kind {
	case yaml.MappingNode:
		return "", goccyError(data, n.Line, n.Column, "cannot unmarshal map[string]interface {} into Go value of type string")
	case yaml.SequenceNode:
		return "", goccyError(data, n.Line, n.Column, "cannot unmarshal []interface {} into Go value of type string")
	case yaml.ScalarNode:
		switch n.Tag {
		case "!!str":
			return n.Value, nil
		case "!!int":
			v, err := parseYAMLInt(n.Value)
			if err != nil {
				return n.Value, nil
			}
			return strconv.FormatInt(v, 10), nil
		case "!!float":
			// handle .inf etc
			lower := strings.ToLower(n.Value)
			if lower == ".inf" || lower == "+.inf" {
				return "+Inf", nil
			}
			if lower == "-.inf" {
				return "-Inf", nil
			}
			if lower == ".nan" {
				return "NaN", nil
			}
			// parse float and format like Go %v for float64
			f, err := parseYAMLFloat(n.Value)
