			if strings.EqualFold(n.Value, "true") {
				return "true", nil
			}
			return "false", nil
		case "!!null":
			return "", nil
		case "!!timestamp":
			return n.Value, nil
		default:
			return n.Value, nil
		}
	case yaml.AliasNode:
		if n.Alias != nil {
			return convertValueNode(data, n.Alias)
		}
		return "", nil
	}
	return "", nil
}

func parseYAMLInt(s string) (int64, error) {
	// Remove underscores
	clean := strings.ReplaceAll(s, "_", "")
	// YAML octal 0o, leading 0, hex
	if strings.HasPrefix(clean, "0x") || strings.HasPrefix(clean, "0X") {
		return strconv.ParseInt(clean[2:], 16, 64)
	}
	if strings.HasPrefix(clean, "0o") || strings.HasPrefix(clean, "0O") {
		return strconv.ParseInt(clean[2:], 8, 64)
	}
	if strings.HasPrefix(clean, "0b") || strings.HasPrefix(clean, "0B") {
		return strconv.ParseInt(clean[2:], 2, 64)
	}
	if len(clean) > 1 && clean[0] == '0' {
		// octal if all digits 0-7, else maybe decimal? yaml.v3 decodes 0123 as octal; 08 as decimal? goccy may...
		if v, err := strconv.ParseInt(clean, 8, 64); err == nil {
			return v, nil
		}
	}
	if strings.HasPrefix(clean, "+") {
		return strconv.ParseInt(clean[1:], 10, 64)
	}
	if strings.HasPrefix(clean, "-") {
		v, err := parseYAMLInt(clean[1:])
		return -v, err
	}
	return strconv.ParseInt(clean, 10, 64)
}
func parseYAMLFloat(s string) (float64, error) {
	clean := strings.ReplaceAll(s, "_", "")
	return strconv.ParseFloat(clean, 64)
}

// goccy-style annotated error
func goccyError(data []byte, line int, col int, msg string) error {
	src := string(data)
	srcLines := strings.Split(src, "\n")
	// If src ends with newline, Split gives trailing empty; original lines are 1-indexed real lines (excluding final empty if resulting)
	// Determine real lines count: if last element empty due to trailing newline, exclude it for display purposes?
	// We'll build display lines from srcLines but trim trailing empty line if src ends with \n
	if strings.HasSuffix(src, "\n") && len(srcLines) > 0 {
		srcLines = srcLines[:len(srcLines)-1]
	}
	if line < 1 {
		line = 1
	}
	if col < 1 {
		col = 1
	}
	start := line - 3
	if start < 1 {
		start = 1
	}
	end := line + 1
	if end > len(srcLines) {
		end = len(srcLines)
	}
	// number width max(2, digits of end)
	width := len(strconv.Itoa(end))
	if width < 2 {
		width = 2
	}
	var b strings.Builder
	b.WriteString(fmt.Sprintf("[%d:%d] %s\n", line, col, msg))
	for i := start; i <= end; i++ {
		marker := " "
		if i == line {
			marker = ">"
		}
		prefix := fmt.Sprintf("%s %*d | ", marker, width, i)
		b.WriteString(prefix + srcLines[i-1] + "\n")
		if i == line {
			caretPrefixLen := len(prefix)
			b.WriteString(strings.Repeat(" ", caretPrefixLen+col-1) + "^\n")
		}
	}
	// Remove trailing newline - caller wraps with Error:...\n final will add a newline via cobra, original error string itself has no trailing newline (cobra adds)
	// Our returned error will be printed as "Error: <err>\n" by cobra, so we should not end with newline - trim final newline
	str := strings.TrimSuffix(b.String(), "\n")
	return fmt.Errorf("%s", str)
}
