func yamlDoubleQuoted(s string) string {
	var b strings.Builder
	b.WriteString("\"")
	for _, r := range s {
		switch r {
		case '"': b.WriteString("\\\"")
		case '\\': b.WriteString("\\\\")
		case '\n': b.WriteString("\\n")
		case '\r': b.WriteString("\\r")
		case '\t': b.WriteString("\\t")
		case '\a': b.WriteString("\\a")
		case '\b': b.WriteString("\\b")
		case '\v': b.WriteString("\\v")
		case '\f': b.WriteString("\\f")
		case 0x1b: b.WriteString("\\e")
		case 0: b.WriteString("\\0")
		default:
			if r < 0x20 || r == 0x7f {
				b.WriteString(fmt.Sprintf("\\x%02x", r))
			} else {
				b.WriteRune(r)
			}
		}
	}
	b.WriteString("\"")
	return b.String()
