# read key file etc: parseTimeStr usages
# latestEntry uses secretVersion
# Now fix Created handling: in write, nowStr variable and entry creation
t=t.replace('''	nowStr := time.Now().UTC().Format(time.RFC3339Nano)''', '''	nowT := time.Now().UTC()''')
t=t.replace('kf.Values[strconv.Itoa(newVersion)] = secretVersion{Created: nowStr, CreatedBy: userArn, Version: newVersion, Value: value}',
            'kf.Values[strconv.Itoa(newVersion)] = secretVersion{Created: nowT, CreatedBy: userArn, Version: newVersion, Value: value}')
# parseTimeStr(e.Created) -> e.Created
t=t.replace("parseTimeStr(e.Created)", "e.Created")
